class Chan {
  constructor(cap = 0) { this.cap = cap; this.buf = []; this.putQ = []; this.takeQ = []; }
  put(v) { return new Promise(res => {
    if (this.takeQ.length) { const t = this.takeQ.shift(); t(v); res(); return; }
    if (this.buf.length < this.cap) { this.buf.push(v); res(); return; }
    this.putQ.push({ v, res });
  }); }
  take() { return new Promise(res => {
    if (this.buf.length) { const v = this.buf.shift(); if (this.putQ.length) { const p = this.putQ.shift(); this.buf.push(p.v); p.res(); } res(v); return; }
    if (this.putQ.length) { const p = this.putQ.shift(); res(p.v); p.res(); return; }
    this.takeQ.push(res);
  }); }
}
const tasks = new Chan(3), results = new Chan(3);
function worker() {
  return (async () => { while (true) { const t = await tasks.take(); if (t === null) break; await results.put({ task: t, val: t * 2 }); } })();
}
(async () => {
  for (let i = 0; i < 3; i++) worker();
  const inputs = [1, 2, 3, 4, 5];
  for (const x of inputs) await tasks.put(x);
  for (let i = 0; i < 3; i++) await tasks.put(null);
  const out = [];
  for (let i = 0; i < inputs.length; i++) out.push(await results.take());
  out.sort((a, b) => a.task - b.task);
  console.log("处理结果:", out.map(o => `t${o.task}->${o.val}`).join(","));
})();
